module obfuscation_check (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [4:0] char_0,\n    input wire [4:0] char_1,\n    input wire [4:0] char_2,\n    input wire [4:0] char_3,\n    input wire [4:0] char_4,\n    input wire [4:0] char_5,\n    input wire [4:0] char_6,\n    input wire [4:0] char_7,\n    input wire [3:0] len,\n    output reg result,\n    output reg done\n);\n\n    // State encoding\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] PROC = 2'd1;\n    localparam [1:0] DONE_ST = 2'd2;\n    \n    reg [1:0] state, next_state;\n    reg [2:0] index, next_index;\n    reg [7:0] seen, next_seen;\n    reg [2:0] next_exp, next_next_exp;\n    reg next_result, next_done;\n\n    wire [4:0] current_char;\n    assign current_char = (index == 3'd0) ? char_0 :\n                          (index == 3'd1) ? char_1 :\n                          (index == 3'd2) ? char_2 :\n                          (index == 3'd3) ? char_3 :\n                          (index == 3'd4) ? char_4 :\n                          (index == 3'd5) ? char_5 :\n                          (index == 3'd6) ? char_6 :\n                          char_7;\n\n    // Combinational next-state logic\n    always @(*) begin\n        next_state = state;\n        next_index = index;\n        next_seen = seen;\n        next_next_exp = next_exp;\n        next_result = result;\n        next_done = 1'b0;\n\n        case (state)\n            IDLE: begin\n                if (start) begin\n                    next_state = PROC;\n                    next_index = 3'd0;\n                    next_seen = 8'd0;\n                    next_next_exp = 3'd0;\n                    next_result = 1'b1;\n                end\n            end\n            \n            PROC: begin\n                if (index < len) begin\n                    if (current_char[4] || (current_char[3:0] > 5'd7)) begin\n                        next_result = 1'b0;\n                        next_state = DONE_ST;\n                        next_done = 1'b1;\n                    end\n                    else if (seen[current_char[2:0]]) begin\n                        next_result = 1'b0;\n                        next_state = DONE_ST;\n                        next_done = 1'b1;\n                    end\n                    else begin\n                        if (current_char[2:0] == next_exp) begin\n                            next_seen = seen | (8'd1 << current_char[2:0]);\n                            next_next_exp = next_exp + 3'd1;\n                            next_index = index + 3'd1;\n                        end\n                        else begin\n                            next_result = 1'b0;\n                            next_state = DONE_ST;\n                            next_done = 1'b1;\n                        end\n                    end\n                end\n                else begin\n                    next_state = DONE_ST;\n                    next_done = 1'b1;\n                    next_result = result;\n                end\n            end\n            \n            DONE_ST: begin\n                next_state = IDLE;\n                next_done = 1'b0;\n            end\n            \n            default: begin\n                next_state = IDLE;\n            end\n        endcase\n    end\n\n    // Sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            index <= 3'd0;\n            seen <= 8'd0;\n            next_exp <= 3'd0;\n            result <= 1'b0;\n            done <= 1'b0;\n        end\n        else begin\n            state <= next_state;\n            index <= next_index;\n            seen <= next_seen;\n            next_exp <= next_next_exp;\n            result <= next_result;\n            done <= next_done;\n        end\n    end\n\nendmodule